const clientJs="const state={cart:[]}; const $=s=>document.querySelector(s); const money=n=>new Intl.NumberFormat('uk-UA',{style:'currency',currency:'UAH',maximumFractionDigits:0}).format(n);\nconst tg=window.Telegram?.WebApp; if(tg){tg.ready();tg.expand();document.body.classList.add('telegram','telegram-mobile');document.body.dataset.telegramUser=tg.initDataUnsafe?.user?.id||'';}\nfetch('/api/products').then(r=>r.json()).then(items=>{ $('#products').innerHTML=items.map(p=>`<article class=\"product\"><span class=\"tag\">${p.category}</span><div class=\"product-info\"><h3>${p.name}</h3><p>${p.format} · ${p.note}</p><div class=\"buy\"><b>${money(p.price)}</b><button data-id=\"${p.id}\">До кошика</button></div></div></article>`).join(''); $('#products').onclick=e=>{const id=e.target.dataset.id;if(id){const p=items.find(x=>x.id===id);state.cart.push(p);render();}}});\nfunction render(){ $('#cartCount').textContent=state.cart.length; $('#cartItems').innerHTML=state.cart.length?state.cart.map((p,i)=>`<div class=\"cart-row\"><div>${p.name}<small>${p.format}</small></div><div><b>${money(p.price)}</b><button data-i=\"${i}\">×</button></div></div>`).join(''):'<p class=\"empty\">Додайте продукт, щоб почати.</p>';$('#total').textContent=money(state.cart.reduce((s,p)=>s+p.price,0));$('#cartItems').onclick=e=>{if(e.target.dataset.i!==undefined){state.cart.splice(+e.target.dataset.i,1);render();}}}\nfunction toggle(show){$('#cart').classList.toggle('open',show);$('#overlay').classList.toggle('open',show)} $('#openCart').onclick=()=>toggle(true);$('#closeCart').onclick=()=>toggle(false);$('#overlay').onclick=()=>toggle(false);\n$('#checkout').onclick=async()=>{if(!state.cart.length)return toggle(true);const r=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:state.cart.map(p=>({productId:p.id,quantity:1})),telegramInitData:tg?.initData||''})});if(r.ok){const o=await r.json();if(tg)tg.showAlert(`Замовлення ${o.orderId} створено`);else alert(`Замовлення ${o.orderId} створено. Ми зв’яжемося з вами для підтвердження.`);state.cart=[];render();toggle(false);}};\n$('#subscribe').onsubmit=e=>{e.preventDefault();e.target.innerHTML='<strong>Дякуємо — ви у списку HERBIO.</strong>';};\n";
