const infoPage=(content)=>"<!doctype html><html lang=\"uk\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>HERBIO | Здоров’я та краса</title><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Manrope:wght@400;500;600;700&display=swap\" rel=\"stylesheet\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><div class=\"announcement\">Безкоштовна доставка від 2 000 ₴ · Турбота — у вашому ритмі</div>"+sharedHeader+content+"</body></html>";
const catalogPage="<main class=\"info-page\"><p class=\"eyebrow\">КАТАЛОГ HERBIO</p><h1>Ваш щоденний баланс</h1><p>Оберіть категорію або перегляньте всі продукти.</p><div class=\"filters\"><button class=\"active\" data-filter=\"all\">Усі</button><button data-filter=\"beauty\">Краса</button><button data-filter=\"energy\">Енергія</button><button data-filter=\"balance\">Баланс</button></div><div class=\"catalog-grid\" id=\"catalogGrid\"><article class=\"catalog-card\" data-cat=\"beauty\"><p class=\"eyebrow\">КРАСА</p><h3>Колагенові пептиди</h3><p>Порошок · 300 г</p><b>1 190 ₴</b></article><article class=\"catalog-card\" data-cat=\"energy\"><p class=\"eyebrow\">ЕНЕРГІЯ</p><h3>Спіруліна</h3><p>Таблетки · 120 шт.</p><b>790 ₴</b></article><article class=\"catalog-card\" data-cat=\"balance\"><p class=\"eyebrow\">БАЛАНС</p><h3>Магній</h3><p>Капсули · 90 шт.</p><b>690 ₴</b></article><article class=\"catalog-card\" data-cat=\"beauty\"><p class=\"eyebrow\">ДОГЛЯД</p><h3>Пептидний комплекс</h3><p>Капсули · 60 шт.</p><b>1 490 ₴</b></article></div><script>document.querySelectorAll(\"[data-filter]\").forEach(b=>b.onclick=()=>{document.querySelectorAll(\"[data-filter]\").forEach(x=>x.classList.remove(\"active\"));b.classList.add(\"active\");document.querySelectorAll(\"[data-cat]\").forEach(x=>x.style.display=b.dataset.filter===\"all\"||x.dataset.cat===b.dataset.filter?\"block\":\"none\")})</script></main>";
